import base64, datetime, json, os, time
import boto3
sqs = boto3.client('sqs')
sns = boto3.client('sns')
def handler(event, context):
    if event.get('rawPath') != '/' + os.environ['PATH_ID']:
        return {'statusCode': 404, 'body': 'unknown path'}
    raw = event.get('body') or '{}'
    if event.get('isBase64Encoded'): raw = base64.b64decode(raw).decode()
    try: message = json.loads(raw)
    except ValueError: return {'statusCode': 400, 'body': 'invalid JSON'}
    if message.get('TopicArn') != os.environ['TOPIC_ARN']:
        return {'statusCode': 403, 'body': 'unexpected topic'}
    now = time.time()
    age = None
    confirmation = None
    if message.get('Type') == 'SubscriptionConfirmation':
        response = sns.confirm_subscription(TopicArn=os.environ['TOPIC_ARN'], Token=message['Token'], AuthenticateOnUnsubscribe='true')
        confirmation = {'SubscriptionArn': response['SubscriptionArn']}
        status = 200
    elif message.get('Type') == 'Notification':
        age = now - datetime.datetime.fromisoformat(message['Timestamp'].replace('Z', '+00:00')).timestamp()
        status = int(os.environ['STATUS'])
    else:
        status = 200
    safe = dict(message)
    for key in ('Token', 'SubscribeURL'):
        if key in safe: safe[key] = '[REDACTED confirmation token]'
    if message.get('Type') in ('SubscriptionConfirmation', 'UnsubscribeConfirmation'):
        safe['Message'] = '[REDACTED confirmation text containing token]'
    record = {'received_at': datetime.datetime.fromtimestamp(now, datetime.timezone.utc).isoformat(timespec='milliseconds'), 'received_unix': now, 'message_age_seconds': age, 'handler_request_id': context.aws_request_id, 'message': safe, 'response': {'statusCode': status, 'body': 'observed status ' + str(status)}}
    if confirmation: record['confirmation'] = confirmation
    sqs.send_message(QueueUrl=os.environ['QUEUE_URL'], MessageBody=json.dumps(record))
    return record['response']

